contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v, uint a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (v)); require(v <= 1000000000000000000000000000000);
        require(address(this).balance >= v, "insufficient balance for deposit");
        require(v >= c.MinSum(), "deposit must meet MinSum");
        require(a >= c.MinSum(), "collect amount must meet MinSum");
        require(a <= v, "collect amount must not exceed deposit");

        c.Deposit{value: v}(); if (__ESBMC_reverted()) return;

        uint beforeCollectBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeCollectEth = address(this).balance;

        bool collectReverted;
        c.Collect(a); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            collectReverted = true;
        } else {
            collectReverted = false;
        }

        assert(!collectReverted && c.balances(address(this)) == beforeCollectBal - a && address(this).balance == beforeCollectEth + a);
    }

    receive() external payable {}
}

