pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 v, uint256 a) internal {
        v = bound(v, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= v);
        vm.assume(v >= c.MinSum());
        vm.assume(a >= c.MinSum());
        vm.assume(a <= v);
        try c.Deposit{value: v}() {} catch { return; }
        uint256 beforeCollectBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeCollectBal = __r; } catch { return; }
        uint beforeCollectEth = address(this).balance;
        bool collectReverted;
        try c.Collect(a) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }
        assertTrue(!collectReverted && c.balances(address(this)) == beforeCollectBal - a && address(this).balance == beforeCollectEth + a);
    }

    function testFuzz_run(uint256 v, uint256 a) public {
        _run(v, a);
    }

    receive() external payable {}
}
